package com.bancatest.reconciliation.domain.model.vo;

import java.util.UUID;

/** Identity of a reconciliation (UUIDv7 generated by the application, never null). */
public record ReconciliationId(UUID value) {

  public ReconciliationId {
    if (value == null) {
      throw new IllegalArgumentException("Reconciliation id must not be null");
    }
  }
}
